import { isUndefined } from 'lodash-es';
import React from 'react';
import { isElement } from 'react-is';

import { Icon } from '../slots/Icon.js';
import { Label } from '../slots/Label.js';
import { Legend } from '../slots/Legend.js';
import { Max } from '../slots/Max.js';
import { Min } from '../slots/Min.js';
import { Segment } from '../slots/Segment.js';
import { Tooltip } from '../slots/Tooltip.js';
import { Value } from '../slots/Value.js';
import { MultiMeterBarChartSlots } from '../types/multi-meter-bar-chart-config.js';

export function iterateSlots(children?: React.ReactNode) {
  const slots: MultiMeterBarChartSlots = { segments: [] };

  React.Children.forEach(children, (child) => {
    if (isElement(child)) {
      switch (child.type) {
        case Label:
          slots.label = child.props.children;
          break;
        case Icon:
          slots.icon = child.props.children;
          break;
        case Value:
          slots.value = {
            value: child.props.children,
            auto: isUndefined(child.props.children),
          };
          break;
        case Min:
          slots.min = {
            value: child.props.children,
            auto: isUndefined(child.props.children),
          };
          break;
        case Max:
          slots.max = {
            value: child.props.children,
            auto: isUndefined(child.props.children),
          };
          break;
        case Segment: {
          const { value, color, name } = child.props;
          slots.segments = [...slots.segments, { value, color, name }];
          break;
        }
        case Legend: {
          slots.legend = true;
          break;
        }
        case Tooltip: {
          const { variant } = child.props;
          slots.tooltip = { enabled: true, variant };
          break;
        }
      }
    }
  });

  return slots;
}
